from pathlib import Path
from copy import deepcopy
import json, math
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'stereo-course/merzlyak-10-base/lessons'
OUT.mkdir(parents=True,exist_ok=True)
COVER={}
INDEX=json.loads((ROOT/'stereo-course/merzlyak-10-base/source-index.json').read_text())
SOURCES={e['source'].get('exercise'):e for e in INDEX['entries'] if e['source'].get('collection')=='main'}

def mid(a,b,t=.5):return [(1-t)*x+t*y for x,y in zip(a,b)]
def point(m,n,p):m['points'][n]=[round(float(x),9) for x in p];return n
def at(m,n,a,b,t=.5):return point(m,n,mid(m['points'][a],m['points'][b],t))
def model(p,e=(),f=(),planar=False):return {'points':deepcopy(p),'edges':[list(x) for x in e],'faces':[list(x) for x in f],'labelNames':[],'planar':planar,'views':{'neutral':{'label':'Данные задачи','points':[n for n in p if not n.startswith('_')][:8]}}}
def view(m,k,label,seg=(),poly=(),pts=()):
 v={'label':label}
 if seg:v['segments']=[list(x) for x in seg]
 if poly:v['polygon']=list(poly)
 if pts:v['points']=list(pts)
 m['views'][k]=v;return k

def cube(a=1,h=None):
 if h is None:h=a
 p={'A':[0,0,0],'B':[0,a,0],'C':[a,a,0],'D':[a,0,0],'A1':[0,0,h],'B1':[0,a,h],'C1':[a,a,h],'D1':[a,0,h]}
 return model(p,[('A','B'),('B','C'),('C','D'),('D','A'),('A1','B1'),('B1','C1'),('C1','D1'),('D1','A1'),('A','A1'),('B','B1'),('C','C1'),('D','D1')],[('A','B','C','D'),('A1','B1','C1','D1'),('A','B','B1','A1'),('B','C','C1','B1'),('C','D','D1','C1'),('D','A','A1','D1')])
def tetra(p=None):
 p=p or {'A':[0,0,0],'B':[1,0,0],'C':[.5,math.sqrt(3)/2,0],'D':[.5,math.sqrt(3)/6,math.sqrt(2/3)]}
 return model(p,[('A','B'),('B','C'),('C','A'),('A','D'),('B','D'),('C','D')],[('A','B','C'),('A','B','D'),('B','C','D'),('C','A','D')])
def base4(p):return model(p,[('A','B'),('B','C'),('C','D'),('D','A')],[('A','B','C','D')])
def plane(m,z=0,size=2,name='p'):
 names=['_'+name+str(i) for i in range(4)]
 for n,p in zip(names,[[-size,-size,z],[size,-size,z],[size,size,z],[-size,size,z]]):point(m,n,p)
 m['faces'].append(names)
 return names

def st(title,text,v='neutral',why='Используем данное условие и свойства указанной фигуры.',prompt=None):return {'title':title,'prompt':prompt or title+' — выполните этот шаг самостоятельно.','explanation':text,'view':v,'justifications':[{'kind':'theorem','text':why}]}
def save(p,n,title,statement,m,steps,answer=None,sub=None,hint=None):
 num=f'{p}.{n}';id=f'ex-{p:02d}-{n:03d}'+('-'+str(sub) if sub else '')
 src=deepcopy(SOURCES[num]['source']);src.pop('paragraph',None)
 if sub:src['subpart']=str(sub)
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 assert 3<=len(steps)<=7,(id,len(steps))
 d={'schemaVersion':1,'revision':1,'id':id,'kind':'exercise','title':num+(f'({sub})' if sub else '')+'. '+title,'status':'draft','source':src,'statement':{'text':statement,'goal':title+'. Обоснуйте результат.'},'visualization':{'type':'scene3d','caption':'Авторская схема условия и построения. Координаты подобраны для наглядности; длины и углы следует доказывать, а не измерять по изображению.','model':m},'help':[{'id':'help-1','question':'Подсказка к первому шагу','text':hint or steps[0]['explanation']}],'steps':steps,'answer':{'mode':'manual','prompt':answer or 'Запишите доказательство или ответ и объясните каждый переход. Доказательство обсуждается с учителем и автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 (OUT/(id+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 c=COVER.setdefault(num,{'sourceId':SOURCES[num]['id'],'exercise':num,'printedPages':src['printedPages'],'pdfPages':src['pdfPages'],'requiredParts':[],'lessonIds':[]})
 c['requiredParts'].append(str(sub) if sub else None);c['lessonIds'].append(id)

SOURCES['19.3']['source'].update(printedPages=[173,174],pdfPages=[174,175])
def pyramid(base,apex,ap='S'):
 p=deepcopy(base);p[ap]=apex;names=list(base)
 return model(p,[(names[i],names[(i+1)%len(names)]) for i in range(len(names))]+[(n,ap) for n in names],[names]+[[names[i],names[(i+1)%len(names)],ap] for i in range(len(names))])
def regular(n=3,a=2,h=2,ap='S'):
 r=a/(2*math.sin(math.pi/n));names=list('ABCDEFGH')[:n]
 if n==4:p={'A':[-a/2,-a/2,0],'B':[-a/2,a/2,0],'C':[a/2,a/2,0],'D':[a/2,-a/2,0]}
 else:p={name:[r*math.cos(math.tau*i/n),r*math.sin(math.tau*i/n),0] for i,name in enumerate(names)}
 m=pyramid(p,[0,0,h],ap);point(m,'O',[0,0,0]);at(m,'K',names[0],names[1]);m['views']['neutral']['points']=[ap]+names[:6]
 view(m,'height','Высота и проекция бокового ребра',seg=[(ap,'O'),('O','A'),(ap,'A')],pts=[ap,'O','A'])
 view(m,'apothem','Апофема и радиус вписанной окружности',seg=[(ap,'K'),('O','K'),(ap,'O')],poly=[ap,'O','K'],pts=[ap,'O','K','A','B'])
 view(m,'face','Боковая грань',poly=[ap,'A','B'],pts=[ap,'A','B','K'])
 return m

def edge_height(m,ap='S',foot='O',vertex='A'):
 view(m,'height','Высота и боковое ребро',seg=[(ap,foot),(foot,vertex),(ap,vertex)],poly=[ap,foot,vertex],pts=[ap,foot,vertex])
def foot(m,name,p,a,b):
 q=m['points'][p];u=m['points'][a];w=[y-x for x,y in zip(u,m['points'][b])];t=sum((x-y)*z for x,y,z in zip(q,u,w))/sum(z*z for z in w)
 return point(m,name,[x+t*y for x,y in zip(u,w)])

# Elementary counts and construction.
for n in [1,2,3]:
 m=regular(5 if n in [1,3] else 3)
 if n==1:statement='Сколько вершин, граней и рёбер имеет n-угольная пирамида?';ss=[st('Вершины','В основании n вершин, вне его одна вершина пирамиды. Всего n+1.'),st('Грани','Одно основание и n треугольных боковых граней. Всего n+1.'),st('Рёбра','Основание содержит n рёбер, ещё n соединяют его вершины с вершиной пирамиды. Всего 2n. Здесь n≥3; схема показывает пример n=5.')]
 elif n==2:statement='Какое наименьшее количество граней может иметь пирамида?';ss=[st('Минимальное основание','Многоугольник имеет не менее трёх сторон. Поэтому наименьшее основание — треугольник.'),st('Боковые грани','Каждой стороне основания соответствует одна боковая грань. При трёх сторонах их три.'),st('Ответ','Добавляем основание: 3+1=4 грани. Пример — треугольная пирамида на схеме.')]
 else:statement='Докажите, что количество рёбер любой пирамиды является чётным числом.';ss=[st('Рёбра основания','Пусть в основании n сторон; тогда основание содержит n рёбер.'),st('Боковые рёбра','От вершины пирамиды идёт по одному ребру к каждой из n вершин основания, то есть ещё n рёбер.'),st('Чётность','Общее количество n+n=2n делится на 2. Значит оно чётно для любой пирамиды.')]
 save(18,n,'Элементы пирамиды',statement,m,ss)
for n in [4,5]:
 m=regular(3 if n==4 else 4);a,b=('B','C') if n==4 else ('A','D');at(m,'H',a,b);v='A' if n==4 else 'C'
 view(m,'projection','Угол бокового ребра с основанием',seg=[('S',v),('O',v),('S','O')],pts=['S','O',v]);view(m,'dihedral','Линейный угол двугранного угла',seg=[('S','H'),('O','H')],pts=['S','O','H',a,b])
 save(18,n,'Высота и два угла правильной пирамиды',f'Изобразите в правильной {"треугольной SABC" if n==4 else "четырёхугольной SABCD"} пирамиде: 1) высоту; 2) угол наклона ребра S{v} к основанию; 3) линейный угол двугранного угла при ребре {a}{b}.',m,[st('Высота','Отметьте центр основания O и соедините с S. По определению правильной пирамиды SO перпендикулярна основанию.','height'),st('Проекция бокового ребра',f'Проекция S{v} на основание — O{v}. Поэтому угол ребра с основанием — ∠S{v}O.','projection'),st('Линейный угол',f'Пусть H — середина {a}{b}. В правильном основании OH ⟂ {a}{b}; в равнобедренной боковой грани SH ⟂ {a}{b}. Поэтому искомый линейный угол — ∠SHO.','dihedral')])
m=regular(3,12,12)
save(18,6,'Высота треугольной пирамиды','Сторона основания правильной треугольной пирамиды равна 12 см, боковое ребро образует с основанием угол 60°. Найдите высоту.',m,[st('Проекция ребра','В равностороннем основании радиус OA=12/√3=4√3 см.','height'),st('Прямоугольный треугольник','∠SAO=60°, SO ⟂ OA. Поэтому SO=OA·tan60°.','height'),st('Вычисление','SO=4√3·√3=12 см.','height')])
m=regular(4,8*math.sqrt(2),8)
save(18,7,'Сторона квадратного основания','Высота правильной четырёхугольной пирамиды равна 8 см, боковое ребро наклонено к основанию под углом 45°. Найдите сторону основания.',m,[st('Проекция ребра','В прямоугольном SOA угол SAO=45°. Поэтому OA=SO/tan45°=8 см.','height'),st('Диагональ квадрата','OA — половина диагонали: a√2/2=8.','height'),st('Сторона','a=16/√2=8√2 см.','height')])
