save(18,8,'Апофема и двугранный угол','Сторона основания правильной четырёхугольной пирамиды 6 см, высота 4 см. Найдите: 1) апофему; 2) двугранный угол при ребре основания.',m,[st('Перпендикулярное сечение','K — середина стороны AB. OK=6/2=3, SO=4. Линейный угол двугранного угла — ∠SKO.','apothem'),st('Апофема','SK=√(SO²+OK²)=√(16+9)=5 см.','apothem'),st('Угол','tan∠SKO=SO/OK=4/3. Ответ: 1) 5 см; 2) arctg(4/3).','apothem')])
m=regular(3,6,1)
