m=regular(7,10,math.sqrt(400-(5/math.tan(math.pi/7))**2))
save(18,10,'Боковая поверхность семиугольной пирамиды','Сторона основания правильной семиугольной пирамиды равна 10 см, апофема 20 см. Найдите площадь боковой поверхности.',m,[st('Периметр','Основание имеет 7 равных сторон: P=7·10=70 см.','face'),st('Площадь всех граней','Площадь каждой треугольной грани равна половине произведения её основания на общую апофему. Поэтому Sбок=Pl/2.','apothem'),st('Результат','Sбок=70·20/2=700 см².','apothem')])
