save(18,33,'Площадь основания по рёбрам','В пирамиде DABC ∠ABC=120°, AB=BC. Каждое боковое ребро равно 8 см и образует с основанием угол 45°. Найдите площадь основания.',m,[st('Радиус описанной окружности','Пусть O — основание высоты. OA=OB=OC=8cos45°=4√2, поэтому R=4√2.','height'),st('Стороны основания','Углы A и C равны (180°−120°)/2=30°. По теореме синусов AB=BC=2Rsin30°=4√2.','base'),st('Площадь','S(ABC)=(1/2)AB·BC·sin120°=(1/2)·32·√3/2=8√3 см².','base')])
