save(18,34,'Равные рёбра над равнобедренным треугольником','В основании равнобедренный треугольник: боковые стороны 3√10 см, основание 6 см. Высота пирамиды 5 см, боковые рёбра равны. Найдите боковое ребро.',m,[st('Площадь основания','Высота к стороне 6 равна √((3√10)²−3²)=9. Площадь основания Δ=6·9/2=27 см².','base'),st('Радиус описанной окружности','Из равенства боковых рёбер основание высоты равноудалено от вершин. R=abc/(4Δ)=(3√10)²·6/(4·27)=5 см.','base'),st('Ребро','Боковое ребро l=√(h²+R²)=√(25+25)=5√2 см.','height')])
