save(18,59,'Треугольник над касательной к вписанной окружности','В ABC AB=BC=25 см, AC=14 см. К вписанной окружности проведена касательная, параллельная AC и пересекающая AB,BC в M,K. Найдите площадь MBK.',m,[st('Высота и площадь основания','BH=√(25²−7²)=24 см. S(ABC)=14·24/2=168 см².','height'),st('Радиус окружности','Полупериметр p=(25+25+14)/2=32. Радиус r=S/p=168/32=21/4.','height'),st('Высота малого треугольника','Касательные AC и MK расположены по разные стороны окружности, расстояние между ними 2r=21/2. Поэтому BT=24−21/2=27/2.','section'),st('Подобие и площадь','MBK ∼ ABC, коэффициент BT/BH=(27/2)/24=9/16. S(MBK)=168·(9/16)²=1701/32 см².','section')])

# §19. Frustums. The top base is a homothetic image of the bottom base.
def frustum_custom(bottom,top):
 names=list(bottom);p=deepcopy(bottom);p.update(top);e=[];f=[names,[n+'1' for n in names]]
 for i,a in enumerate(names):
  b=names[(i+1)%len(names)];e.extend([(a,b),(a+'1',b+'1'),(a,a+'1')]);f.append([a,b,b+'1',a+'1'])
 m=model(p,e,f);m['views']['neutral']['points']=(names+[n+'1' for n in names])[:8]
 return m

def frustum(n,a,b,h):
 names=list('ABCDEF')[:n];R=a/(2*math.sin(math.pi/n))
 if n==4:bottom={'A':[-a/2,-a/2,0],'B':[-a/2,a/2,0],'C':[a/2,a/2,0],'D':[a/2,-a/2,0]}
 else:bottom={q:[R*math.cos(i*math.tau/n),R*math.sin(i*math.tau/n),0] for i,q in enumerate(names)}
 top={q+'1':[p[0]*b/a,p[1]*b/a,h] for q,p in bottom.items()};m=frustum_custom(bottom,top)
 point(m,'O',[0,0,0]);point(m,'O1',[0,0,h]);at(m,'K','A','B');at(m,'K1','A1','B1');point(m,'H',[m['points']['K1'][0],m['points']['K1'][1],0]);point(m,'T',[m['points']['A1'][0],m['points']['A1'][1],0])
 view(m,'apothem','Апофема KK₁ и её проекция KH',poly=['K','K1','H'],seg=[('K','K1'),('K1','H')],pts=['K','K1','H','O','O1'])
 view(m,'edge','Боковое ребро и его проекция',poly=['A','A1','T'],seg=[('A','A1'),('A1','T')],pts=['A','A1','T','O','O1'])
 view(m,'face','Боковая трапеция',poly=['A','B','B1','A1'],seg=[('K','K1')],pts=['A','B','A1','B1','K','K1'])
 return m
