save(19,11,'Боковая поверхность наклонной усечённой пирамиды','BB₁ усечённой пирамиды ABCA₁B₁C₁ перпендикулярно основанию. BB₁=4 см, AB=BC=16 см, A₁B₁=B₁C₁=10 см, ∠ABC=120°. Найдите боковую поверхность.',m,[st('Две прямоугольные трапеции','Грани ABB₁A₁ и CBB₁C₁ имеют основания 16 и 10 и высоту BB₁=4. Каждая площадь равна (16+10)·4/2=52.','vertical'),st('Основания третьей грани','В равнобедренных основаниях угол B=120°. Поэтому AC=16√3, A₁C₁=10√3, расстояния B до AC и B₁ до A₁C₁ равны 8 и 5.','third'),st('Высота третьей трапеции','P,Q — середины AC,A₁C₁. Проекция PQ имеет длину 8−5=3, вертикальная составляющая 4. Значит PQ=5. Площадь третьей грани (16√3+10√3)·5/2=65√3.','third'),st('Сумма','Sбок=52+52+65√3=104+65√3 см².','neutral')])
