save(19,12,'Усечённая пирамида с вертикальной гранью','Основания ABCDA₁B₁C₁D₁ — квадраты, AD=4 см, A₁D₁=2 см. Грань AA₁B₁B — равнобокая трапеция в плоскости, перпендикулярной основанию. Угол плоскостей CC₁D₁D и основания 60°. Найдите боковую поверхность.',m,[st('Положение меньшего квадрата','В вертикальной равнобокой грани верхнее основание расположено симметрично над нижним. Проекция верхнего квадрата отступает на 1 от сторон AD,BC, на 0 от AB и на 2 от CD.','neutral'),st('Высота и задняя грань','Проекция высоты PQ грани CC₁D₁D равна 2. Поэтому высота усечённой пирамиды h=2tan60°=2√3, PQ=2/cos60°=4. Площадь задней грани (4+2)·4/2=12.','back'),st('Остальные грани','Вертикальная грань имеет площадь (4+2)h/2=6√3. Высота каждой из двух остальных граней √(h²+1²)=√13, площадь каждой 3√13.','side'),st('Сумма','Sбок=12+6√3+6√13=6(2+√13+√3) см².','neutral')])
